namespace App\Filament\Exports;

use App\Models\MatrixRecord;
use Filament\Actions\Exports\ExportColumn;
use Filament\Actions\Exports\Exporter;
use Filament\Actions\Exports\Models\Export;
use Illuminate\Support\Number;

/**
 * Generated exporter for Matrix Records records (CSV/XLSX).
 */
class MatrixRecordExporter extends Exporter
{
    protected static ?string $model = MatrixRecord::class;

    /**
     * Columns included in the export.
     * @return  array  Export column definitions.
     */
    public static function getColumns(): array
    {
        return [
                        ExportColumn::make('id')->limit(50)->label('Id'),
            ExportColumn::make('txt_plain')->limit(50)->label('Plain Text'),
            ExportColumn::make('txt_email')->limit(50)->label('Email'),
            ExportColumn::make('txt_url')->limit(50)->label('Url'),
            ExportColumn::make('txt_tel')->limit(8)->label('Telephone'),
            ExportColumn::make('txt_password')->limit(50)->label('Password'),
            ExportColumn::make('num_int')->limit(50)->label('Integer'),
            ExportColumn::make('num_decimal')->limit(50)->label('Decimal'),
            ExportColumn::make('dt_date')->limit(50)->label('Date'),
            ExportColumn::make('dt_datetime')->limit(50)->label('Datetime'),
            ExportColumn::make('txt_area')->limit(50)->label('Text Area'),
            ExportColumn::make('txt_rich')->limit(50)->label('Rich Editor'),
            ExportColumn::make('bool_check')->limit(50)->label('Checkbox'),
            ExportColumn::make('opt_dropdown')->limit(50)->label('Options Dropdown'),
            ExportColumn::make('opt_radios')->limit(50)->label('Options Radios'),
            ExportColumn::make('opt_checkboxes')->limit(50)->label('Options Checkboxes'),
            ExportColumn::make('opt_multi')->limit(50)->label('Options Multi'),
            ExportColumn::make('character.nama_watak')->limit(50)->label('Nama Watak'),
            ExportColumn::make('character.nama_watak')->limit(50)->label('Nama Watak'),
            ExportColumn::make('rep_simple')->limit(50)->listAsJson()->label('Repeater Simple'),
            ExportColumn::make('rep_complex')->limit(50)->listAsJson()->label('Repeater Complex'),
            ExportColumn::make('img_profile')->limit(50)->label('Profile Picture'),
            ExportColumn::make('img_avatar')->limit(50)->label('Avatar Circular'),
            ExportColumn::make('file_doc')->limit(50)->label('Document'),
            ExportColumn::make('file_multi')->limit(50)->label('Attachments'),
            ExportColumn::make('map_loc')->limit(50)->label('Location Map'),
            ExportColumn::make('vid_clip')->limit(50)->label('Video Clip'),
            ExportColumn::make('color_hex')->limit(50)->label('Event Color'),
        ];
    }

    /**
     * Notification body shown when the export finishes.
     *
     * @param  Export  $export  The completed export job.
     * @return  string  Human-readable completion summary.
     */
    public static function getCompletedNotificationBody(Export $export): string
    {
        $body = 'Your Matrix Records export has completed and ' . Number::format($export->successful_rows) . ' ' . str('row')->plural($export->successful_rows) . ' exported.';

        if ($failedRowsCount = $export->getFailedRowsCount()) {
            $body .= ' ' . Number::format($failedRowsCount) . ' ' . str('row')->plural($failedRowsCount) . ' failed to export.';
        }

        return $body;
    }
}
